// We make a new blueprint that copies the normal Button
class CreateButton extends Button {

    // Our custom factory worker
    constructor(x, y, text, color, borders) {
        super(); // This calls the original Button factory first

        // Then we customize it automatically!
        this.x = x;
        this.y = y;
        this.text = text;
        this.color = color;
        this.borders = borders;
    }
}

// We make a new blueprint that copies the normal Box
class CreateBox extends Box {

    // Our custom factory worker
    constructor(x, y, color) {
        super(); // This calls the original Box factory first

        // Then we customize it automatically!
        this.x = x;
        this.y = y;        
        this.color = color;

        // Make eyes, mouth, and nose true by default!
        this.eyes = true;
        this.mouth = true;
        this.nose = true;
    }
}

// We make a new blueprint that copies the normal Creeper
class CreateCreeper extends Creeper {

    // Our custom factory worker
    constructor(x, y, color) {
        super(); // This calls the original Creeper factory first

        // Then we customize it automatically!
        this.x = x;
        this.y = y;        
        this.color = color;

        // Make eyes, mouth, and legs true by default!
        this.eyes = true;
        this.mouth = true;
        this.legs = true;
    }
}

